            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos();
        let timing = Self {
70→            started_at: Utc::now(),
            ended_at: None,
            monotonic_ns: monotonic,
            duration_ms: 0,
            duration_ns: 0,
            wallclock_ns: monotonic,
