/// Truncate string to max length
350→fn truncate_string(s: &str, max_len: usize) -> String {
    if s.len() <= max_len {
        s.to_string()
    } else {
        // Walk back from the byte limit to a UTF-8 boundary before slicing.
        let mut boundary = max_len.min(s.len());
        while !s.is_char_boundary(boundary) {
            boundary -= 1;
        }
        format!("{}... (truncated)", &s[..boundary])
360→    }
}

/// Compute execution hash for deterministic fingerprinting
pub fn hash_execution(tool_name: &str, input: &Value, output: &Value, prev_hash: &str) -> String {
